parameters.functionScript:
// `approve: false` is a real answer, so the guard tests `undefined`
// and never falsiness — a decline read as "not ready yet" is a queue
// entry nothing ever removes.
if (Inputs.requestId === undefined || Inputs.approve === undefined) return;
if (String(Inputs.requestId).length === 0) return;
Outputs.requestId = Inputs.requestId;
Outputs.approve = Inputs.approve === true;
Outputs.ready();

// Two producers — the row supplies the user id, the request supplies the
// decision — so this opens with the readiness guard rule 2 prescribes.
if (Inputs.userId === undefined || Inputs.approve === undefined) return;
const userId = Inputs.userId === null ? '' : String(Inputs.userId);
Outputs.userId = userId;
Outputs.approved = Inputs.approve === true;
// The directory row, from the request row that is about to be deleted.
// 🔴 It has to be carried HERE: `remove` takes the queue entry away, so
// after this endpoint runs there is nowhere left holding the person's
// name and address. Everything the projection needs leaves this node.
const email = Inputs.email === undefined || Inputs.email === null ? '' : String(Inputs.email);
const named = Inputs.name === undefined || Inputs.name === null ? '' : String(Inputs.name).trim();
Outputs.email = email;
// Same fallback `requestAccess` uses when a person left the name box
// empty: a directory row with no name at all is a blank line.
Outputs.name = named.length > 0 ? named : email;
Outputs.joinedAt = new Date().toISOString();
Outputs.standing = 'member';
// A row whose userId is missing cannot be approved into anything. It is
// still a queue entry a moderator asked to be rid of, so it declines.
if (Inputs.approve === true && userId.length > 0) {
  Outputs.grant();
  return;
}
Outputs.decline();
